import pandas as pd
import numpy as np

# Load the data
crime_data = pd.read_csv('chunks_csv/moran_local_no2crime_crime_first_half_2014.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Handle missing values
crime_data['value'] = crime_data['value'].fillna(crime_data['value'].median())

# Compute neighborhood statistics
neighborhood_stats = {}
for index, row in crime_data.iterrows():
    neighbors = adjacency_data[adjacency_data['borough'] == row['borough']]
    if not neighbors.empty:
        neighbor_values = crime_data[crime_data['borough'].isin(neighbors['neighbor'])]['value']
        neighborhood_stats[row['borough']] = np.mean(neighbor_values)

# Identify hot and cold spots
hot_cold_spots = {}
for index, row in crime_data.iterrows():
    if not row['borough'] in neighborhood_stats:
        neighborhood_stats[row['borough']] = np.nan
    if row['value'] > neighborhood_stats[row['borough']]:
        hot_cold_spots[row['borough']] = 'HH'
    elif row['value'] < neighborhood_stats[row['borough']]:
        hot_cold_spots[row['borough']] = 'LL'

# Compute statistical method (Moran's I)
moran_i_values = {}
for borough, spot in hot_cold_spots.items():
    if spot == 'HH':
        neighbors = adjacency_data[adjacency_data['borough'] == borough]
        if not neighbors.empty:
            neighbor_values = crime_data[crime_data['borough'].isin(neighbors['neighbor'])]['value']
            moran_i_values[borough] = np.mean(neighbor_values)
    elif spot == 'LL':
        neighbors = adjacency_data[adjacency_data['borough'] == borough]
        if not neighbors.empty:
            neighbor_values = crime_data[crime_data['borough'].isin(neighbors['neighbor'])]['value']
            moran_i_values[borough] = np.mean(neighbor_values)

# List identified boroughs
identified_boroughs = []
for borough, spot in hot_cold_spots.items():
    if spot == 'HH':
        test_statistic = moran_i_values[borough]
        significance_measure = np.mean([np.mean(np.random.choice(crime_data['value'], size=len(crime_data), replace=True)) for _ in range(500)])
        identified_boroughs.append(f"{borough} (HH, test statistic = {test_statistic}, significance measure = {significance_measure})")
    elif spot == 'LL':
        test_statistic = moran_i_values[borough]
        significance_measure = np.mean([np.mean(np.random.choice(crime_data['value'], size=len(crime_data), replace=True)) for _ in range(500)])
        identified_boroughs.append(f"{borough} (LL, test statistic = {test_statistic}, significance measure = {significance_measure})")

# Print the results
print(f"data_points_used = {len(crime_data)}")
print(f"FINAL ANSWER: {', '.join(identified_boroughs)}")
